-- Migration 015: D7's shadow bar as policy keys with platform baselines (ADR-0038/ADR-0057).
--
-- 001_initial.sql seeds these rows when the database file is *created*, so a fresh environment
-- and a migrated one hold the same bars. A database created before these keys existed cannot
-- gain them by being reopened, so each row is inserted here once, idempotently.
--
-- The fingerprints are copied verbatim from the baselines in 001_initial.sql (generated by
-- publishing through PolicyResolver, never hand-computed) — the audit chain checks them.

INSERT INTO policy_defs (policy_key, domain, value_type, risk_level, owner_role, spec_ref, description, created_at)
SELECT 'governance.shadow.min_agreement_rate', 'COMMERCIAL', 'PCT', 'MEDIUM', 'owner', '§16/D7/ADR-0038', 'Minimum agreement rate (as percent) before an agent may graduate from shadow mode; a tenant may set stricter, never looser.', '2026-10-03T00:00:00+00:00'
WHERE NOT EXISTS (SELECT 1 FROM policy_defs WHERE policy_key = 'governance.shadow.min_agreement_rate');

INSERT INTO policy_defs (policy_key, domain, value_type, risk_level, owner_role, spec_ref, description, created_at)
SELECT 'governance.shadow.min_cases', 'COMMERCIAL', 'COUNT', 'MEDIUM', 'owner', '§16/D7/ADR-0038', 'Minimum shadow cases observed before graduation is even measurable; below this the bar cannot mean anything.', '2026-10-03T00:00:00+00:00'
WHERE NOT EXISTS (SELECT 1 FROM policy_defs WHERE policy_key = 'governance.shadow.min_cases');

INSERT INTO policy_revisions (policy_revision_id, agency_id, policy_key, version, value, effective_from, effective_to, source_doc_ref, approved_by, fingerprint, created_at)
SELECT 'polrev_baseline_17', 'agency_default', 'governance.shadow.min_agreement_rate', 1, '95', '2026-10-02', '9999-12-31', 'D7 decision 2026-10-02 / ADR-0038', 'owner_anas', '0d1da33903a7a3e446c4644b6e01d338fbe9c021301ceec2e3b6418834e4a921', '2026-10-02T00:00:00+00:00'
WHERE NOT EXISTS (
    SELECT 1 FROM policy_revisions
    WHERE agency_id = 'agency_default' AND policy_key = 'governance.shadow.min_agreement_rate'
);

